const merged = $input.first().json;
const input = { ...merged, crawl4aiResult: merged };
const OWNER = input.githubOwner || 'bisco401';
const REPO = input.githubRepo || '6ixo';
const BRANCH = input.githubBranch || 'main';
const CSV_PATH = input.csvPath || 'data/scraped-listings.csv';
const TOKEN = input.githubToken;
const DEFAULT_STATUS = input.defaultImportStatus || 'pending';
let SOURCES = [];
try {
  SOURCES = typeof input.sourcesJson === 'string' ? JSON.parse(input.sourcesJson || '[]') : input.sourcesJson;
} catch (error) {
  throw new Error('sourcesJson is not valid JSON. Do not edit it unless you need to add more sources.');
}

if (!TOKEN || TOKEN === 'PASTE_GITHUB_TOKEN_HERE') throw new Error('Paste your GitHub token into the Set Config Here node.');
if (!Array.isArray(SOURCES) || !SOURCES.length) throw new Error('The Set Config Here node needs at least one source in sourcesJson.');

const httpRequest = async (options) => {
  const request = {
    method: options.method || 'GET',
    uri: options.url,
    url: options.url,
    headers: options.headers || {},
    body: options.body,
    json: options.json === true,
    resolveWithFullResponse: true,
    simple: false
  };
  try {
    const response = await this.helpers.httpRequest(request);
    const status = response.statusCode || response.status || 200;
    const body = response.body ?? response;
    return { status, ok: status >= 200 && status < 300, body };
  } catch (error) {
    const status = error.statusCode || error.status || error.response?.status || error.response?.statusCode || 500;
    const body = error.response?.body || error.response?.data || error.message || '';
    return { status, ok: status >= 200 && status < 300, body };
  }
};

const csvHeaders = ['id','status','target_surface','app_category','app_subcategory','title','price_text','price_value','currency','city','country','seller','phone','description','image_urls','source_site','source_url','scraped_at','make','model','trim','year','condition','transmission','color','mileage_km','attributes'];
const ghHeaders = { authorization: `Bearer ${TOKEN}`, accept: 'application/vnd.github+json', 'x-github-api-version': '2022-11-28' };
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const strip = (value = '') => String(value || '').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&#8373;|&#x20b5;/gi, 'GH¢').replace(/\s+/g, ' ').trim();
const rx = (pattern, flags = 'i') => pattern ? new RegExp(pattern, flags) : null;
const firstMatch = (text, pattern, flags = 'i') => {
  const re = rx(pattern, flags);
  if (!re) return '';
  const match = String(text || '').match(re);
  return strip(match?.[1] || match?.[0] || '');
};
const absUrl = (value, base) => {
  try { return new URL(String(value || ''), base || undefined).toString(); }
  catch { return String(value || '').trim(); }
};
const priceValue = (priceText = '') => {
  const parsed = Number(String(priceText || '').replace(/[^0-9.]/g, ''));
  return Number.isFinite(parsed) ? String(parsed) : '';
};
const currency = (priceText = '') => {
  const text = String(priceText || '');
  if (/JA\$|JMD/i.test(text)) return 'JMD';
  if (/GH¢|GHS/i.test(text)) return 'GHS';
  if (/\$/.test(text)) return 'USD';
  if (/£/.test(text)) return 'GBP';
  if (/€/.test(text)) return 'EUR';
  return '';
};
const guessYear = (text = '') => String(String(text || '').match(/\b(19|20)\d{2}\b/)?.[0] || '');
const normalizeCondition = (value = '') => {
  const text = String(value || '').toLowerCase();
  if (/like new/.test(text)) return 'like_new';
  if (/excellent/.test(text)) return 'excellent';
  if (/good/.test(text)) return 'good';
  if (/brand new|\bnew\b/.test(text)) return 'new';
  if (/foreign used|local used|used|pre-owned|preowned/.test(text)) return 'used';
  return '';
};
const csvEscape = (value = '') => {
  const text = String(value ?? '');
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};
const parseCsv = (text = '') => {
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  const pushCell = () => { row.push(cell); cell = ''; };
  const pushRow = () => { pushCell(); if (row.some((v) => String(v || '').trim())) rows.push(row); row = []; };
  const input = String(text || '').replace(/^\uFEFF/, '');
  for (let i = 0; i < input.length; i += 1) {
    const char = input[i];
    const next = input[i + 1];
    if (quoted) {
      if (char === '"' && next === '"') { cell += '"'; i += 1; }
      else if (char === '"') quoted = false;
      else cell += char;
    } else if (char === '"') quoted = true;
    else if (char === ',') pushCell();
    else if (char === '\n') pushRow();
    else if (char !== '\r') cell += char;
  }
  if (cell || row.length) pushRow();
  const headers = (rows.shift() || csvHeaders).map((h) => String(h || '').trim());
  return rows.map((values) => headers.reduce((acc, header, index) => { if (header) acc[header] = values[index] || ''; return acc; }, {}));
};
const toCsv = (rows = []) => [csvHeaders.join(','), ...rows.map((row) => csvHeaders.map((header) => csvEscape(row[header] || '')).join(','))].join('\n') + '\n';
const getGithubCsv = async () => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}?ref=${BRANCH}`;
  const res = await httpRequest({ url, headers: ghHeaders, json: true });
  if (res.status === 404) return { sha: null, text: csvHeaders.join(',') + '\n' };
  if (!res.ok) throw new Error(`Could not read ${CSV_PATH}: ${res.status} ${typeof res.body === 'string' ? res.body : JSON.stringify(res.body)}`);
  const json = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
  return { sha: json.sha, text: Buffer.from(json.content || '', 'base64').toString('utf8') };
};
const putGithubCsv = async (text, sha) => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}`;
  const body = {
    message: 'Update scraped listings CSV',
    branch: BRANCH,
    content: Buffer.from(text, 'utf8').toString('base64'),
    ...(sha ? { sha } : {})
  };
  const res = await httpRequest({ url, method: 'PUT', headers: { ...ghHeaders, 'content-type': 'application/json' }, body, json: true });
  if (!res.ok) throw new Error(`Could not update ${CSV_PATH}: ${res.status} ${typeof res.body === 'string' ? res.body : JSON.stringify(res.body)}`);
  return typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
};
const normalizeWhitespace = (value = '') => strip(String(value || '').replace(/\s+/g, ' '));
const decodeHtml = (value = '') => String(value || '')
  .replace(/&quot;/g, '"')
  .replace(/&#34;/g, '"')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&#x2F;/g, '/');
const extractAttr = (text = '', attr = 'href') => {
  const match = String(text || '').match(new RegExp(attr + "=[\"']([^\"']+)[\"']", 'i'));
  return decodeHtml(match?.[1] || '');
};
const splitMakeModel = (title = '') => {
  const cleaned = normalizeWhitespace(title).replace(/\b(19|20)\d{2}\b.*$/, '').replace(/\b\d+[,.]\d+L\b/i, '').trim();
  const multi = ['Mercedes-Benz', 'Land Rover', 'Rolls Royce', 'Alfa Romeo', 'Aston Martin'];
  const found = multi.find((make) => cleaned.toLowerCase().startsWith(make.toLowerCase()));
  if (found) return { make: found, model: cleaned.slice(found.length).trim() };
  const [make = '', ...rest] = cleaned.split(/\s+/);
  return { make, model: rest.join(' ') };
};
const extractPhoneFromJacarsDetail = (html = '') => {
  const text = String(html || '');
  const whatsapp = text.match(/api\.whatsapp\.com\/send\?phone=([^&"']+)/i);
  if (whatsapp?.[1]) return decodeURIComponent(whatsapp[1]).replace(/\s+/g, '').trim();
  const tel = text.match(/href=["']tel:([^"']+)["']/i);
  if (tel?.[1] && !/\{\{/.test(tel[1])) return decodeURIComponent(tel[1]).replace(/\s+/g, '').trim();
  const visible = text.match(/phone-author-subtext__main[^>]*>([^<]+)<[\s\S]{0,140}?phone-author-subtext__mask[^>]*>([^<]*)</i);
  if (visible?.[1]) return strip(String(visible[1] || '') + String(visible[2] || '')).replace(/\s+/g, '').trim();
  return '';
};
const extractJacarsDetailFields = (html = '') => {
  const text = String(html || '');
  const field = (label) => normalizeWhitespace(firstMatch(text, '<li[^>]*>\\s*\\*?\\s*' + label + ':\\s*([\\s\\S]*?)<\\/li>', 'i'));
  const markdownField = (label) => normalizeWhitespace(firstMatch(text, '\\*\\s*' + label + ':\\s*([^\\n]+)', 'i'));
  return {
    phone: extractPhoneFromJacarsDetail(text),
    color: field('Color') || markdownField('Color'),
    transmission: field('Gearbox') || markdownField('Gearbox'),
    mileage_km: (field('Mileage') || markdownField('Mileage')).replace(/[^0-9]/g, ''),
    description: normalizeWhitespace(firstMatch(text, "<div[^>]+class=[\"'][^\"']*announcement-description[^\"']*[\"'][^>]*>([\\s\\S]*?)<\\/div>", 'i'))
  };
};
const crawlDetailPages = async (urls = []) => {
  const endpoint = input.crawl4aiUrl;
  if (!endpoint || !urls.length) return [];
  const res = await httpRequest({
    url: endpoint,
    method: 'POST',
    body: {
      urls,
      browser_config: { type: 'BrowserConfig', params: { headless: true } },
      crawler_config: { type: 'CrawlerRunConfig', params: { stream: false, cache_mode: 'bypass' } }
    },
    json: true
  });
  if (!res.ok) throw new Error('Crawl4AI detail crawl failed: ' + res.status + ' ' + (typeof res.body === 'string' ? res.body : JSON.stringify(res.body)));
  return normalizeCrawlItems(res.body);
};

const extractJacarsListings = (source, html) => {
  const config = source.extractor_config || {};
  const input = String(html || '');
  const starts = [];
  const startRe = /<div[^>]+class=["'][^"']*\badvert\b[^"']*\bjs-item-listing\b[^"']*["'][^>]*>/gi;
  let match;
  while ((match = startRe.exec(input))) starts.push(match.index);
  const cards = starts.map((start, index) => input.slice(start, starts[index + 1] || input.length));
  const rows = [];
  const seen = new Set();
  for (const card of cards) {
    const id = firstMatch(card, "data-id=[\"']?(\\d+)[\"']?", 'i') || firstMatch(card, "id=[\"']?(\\d+)[\"']?", 'i');
    const titleLink = card.match(/<a[^>]+class=["'][^"']*advert__content-title[^"']*["'][\s\S]*?<\/a>/i)?.[0] || '';
    const title = normalizeWhitespace(titleLink || firstMatch(card, 'advert__content-title[\\s\\S]*?>([\\s\\S]*?)<\\/a>', 'i'));
    if (!title || !/\b(19|20)\d{2}\b/.test(title)) continue;
    const href = extractAttr(titleLink, 'href') || firstMatch(card, "<a[^>]+class=[\"'][^\"']*mask[^\"']*[\"'][^>]+href=[\"']([^\"']+)", 'i') || (id ? '/adv/' + id + '/' : '');
    const sourceUrl = absUrl(href || source.list_url, source.base_url || source.list_url);
    if (seen.has(sourceUrl)) continue;
    seen.add(sourceUrl);
    const priceBlock = card.match(/<a[^>]+class=["'][^"']*advert__content-price[^"']*["'][\s\S]*?<\/a>/i)?.[0] || '';
    let priceText = normalizeWhitespace(priceBlock).replace(/JA\$\s*/i, 'JA$ ');
    if (!priceText) priceText = firstMatch(card, '(JA\\$\\s?[0-9,.]+(?:\\s?JA\\$\\s?[0-9,.]+)?|Call for price)', 'i');
    const place = normalizeWhitespace(firstMatch(card, "<div[^>]+class=[\"'][^\"']*advert__content-place[^\"']*[\"'][^>]*>([\\s\\S]*?)<\\/div>", 'i'));
    const dateText = normalizeWhitespace(firstMatch(card, "<div[^>]+class=[\"'][^\"']*advert__content-date[^\"']*[\"'][^>]*>([\\s\\S]*?)<\\/div>", 'i'));
    const seller = normalizeWhitespace(firstMatch(card, 'advert__header-name[\\s\\S]*?<span>([\\s\\S]*?)<\\/span>', 'i')) || source.name || '';
    const imageMatches = [
      ...card.matchAll(/data-background=["']([^"']+)["']/gi),
      ...card.matchAll(/background-image:\s*url\((?:&quot;|["']?)(.*?)(?:&quot;|["']?)\)/gi),
      ...card.matchAll(/<img[^>]+src=["']([^"']+)["']/gi)
    ].map((m) => decodeHtml(m[1])).filter(Boolean).map((url) => absUrl(url, source.base_url || source.list_url));
    const images = [...new Set(imageMatches)].join('|');
    const year = guessYear(title);
    const { make, model } = splitMakeModel(title);
    rows.push({
      id: id ? 'jacars-' + id : 'csv-' + Math.abs([...sourceUrl].reduce((a, c) => ((a << 5) - a + c.charCodeAt(0)) | 0, 0)),
      status: source.default_status || DEFAULT_STATUS,
      target_surface: 'vehicles',
      app_category: 'vehicles',
      app_subcategory: source.app_subcategory || 'cars',
      title,
      price_text: priceText,
      price_value: priceValue(priceText),
      currency: currency(priceText) || 'JMD',
      city: place,
      country: config.country || 'Jamaica',
      seller,
      phone: '',
      description: [title, priceText, place, dateText].filter(Boolean).join(' - '),
      image_urls: images,
      source_site: source.name || 'JACars',
      source_url: sourceUrl,
      scraped_at: new Date().toISOString(),
      make,
      model,
      trim: '',
      year,
      condition: 'used',
      transmission: '',
      color: '',
      mileage_km: '',
      attributes: JSON.stringify({ sourceDate: dateText, parser: 'jacars' })
    });
  }
  return rows;
};

const extractListings = (source, html) => {
  const config = source.extractor_config || {};
  if (String(config.parser || '').toLowerCase() === 'jacars' || /jacars/i.test(source.name || '')) return extractJacarsListings(source, html);
  const base = source.base_url || source.list_url;
  const cardRe = rx(config.cardPattern, 'gi');
  const cards = cardRe ? Array.from(String(html || '').matchAll(cardRe)).map((m) => m[0]) : [html];
  return cards.map((card) => {
    const title = firstMatch(card, config.titlePattern || '<h[12][^>]*>([\\s\\S]*?)<\\/h[12]>', 'i') || firstMatch(card, config.fallbackTitlePattern || 'title="([^"]+)"', 'i');
    const href = firstMatch(card, config.urlPattern || 'href="([^"]+)"', 'i');
    const sourceUrl = absUrl(href || source.list_url, base);
    const priceText = firstMatch(card, config.pricePattern || '(GH¢|GHS|\\$|£|€)\\s?[0-9,.]+', 'i');
    const image = firstMatch(card, config.imagePattern || '<img[^>]+src="([^"]+)"', 'i');
    const location = firstMatch(card, config.locationPattern || '', 'i');
    const description = firstMatch(card, config.descriptionPattern || '', 'i') || strip(card).slice(0, 280);
    const attributes = {
      employmentType: config.employmentType || '',
      experienceLevel: config.experienceLevel || '',
      remote: Boolean(config.remote),
      tags: Array.isArray(config.tags) ? config.tags : []
    };
    const row = {
      id: sourceUrl ? `csv-${Math.abs([...sourceUrl].reduce((a, c) => ((a << 5) - a + c.charCodeAt(0)) | 0, 0))}` : `csv-${Date.now()}`,
      status: source.default_status || DEFAULT_STATUS,
      target_surface: source.target_surface || (source.app_category === 'vehicles' ? 'vehicles' : 'marketplace'),
      app_category: source.app_category || 'electronics',
      app_subcategory: source.app_subcategory || '',
      title,
      price_text: priceText,
      price_value: priceValue(priceText),
      currency: currency(priceText),
      city: config.city || location.split(',')[0]?.trim() || '',
      country: config.country || '',
      seller: firstMatch(card, config.sellerPattern || '', 'i') || config.seller || source.name,
      phone: firstMatch(card, config.phonePattern || '(\\+?\\d[\\d\\s().-]{7,}\\d)', 'i') || config.phone || '',
      description,
      image_urls: image ? absUrl(image, base) : '',
      source_site: source.name || '',
      source_url: sourceUrl,
      scraped_at: new Date().toISOString(),
      make: firstMatch(card, config.makePattern || '', 'i') || config.make || '',
      model: firstMatch(card, config.modelPattern || '', 'i') || config.model || '',
      trim: firstMatch(card, config.trimPattern || '', 'i') || config.trim || '',
      year: firstMatch(card, config.yearPattern || '', 'i') || guessYear(`${title} ${description}`),
      condition: firstMatch(card, config.conditionPattern || '', 'i') || normalizeCondition(`${title} ${description}`),
      transmission: firstMatch(card, config.transmissionPattern || '(Automatic|Manual)', 'i'),
      color: firstMatch(card, config.colorPattern || '', 'i') || config.color || '',
      mileage_km: firstMatch(card, config.mileagePattern || '', 'i'),
      attributes: JSON.stringify(attributes)
    };
    return row;
  }).filter((row) => row.title && row.source_url);
};

const normalizeCrawlItems = (value) => {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap(normalizeCrawlItems);
  if (Array.isArray(value.results)) return value.results;
  if (Array.isArray(value.data)) return value.data;
  if (value.body) return normalizeCrawlItems(value.body);
  return [value];
};
const crawlItems = normalizeCrawlItems(input.crawl4aiResult || input);
const crawlByUrl = new Map();
for (const item of crawlItems) {
  const url = String(item.url || item.redirected_url || '').trim();
  const text = item.html || item.cleaned_html || item.fit_html || item.markdown?.raw_markdown || item.markdown || item.fit_markdown || '';
  if (url) crawlByUrl.set(url, text);
  if (!url && text) crawlByUrl.set('__fallback__', text);
}

const existing = await getGithubCsv();
const rowsByUrl = new Map(parseCsv(existing.text).map((row) => [String(row.source_url || '').trim(), row]));
const summary = [];
for (const source of SOURCES.filter((item) => item && item.enabled !== false)) {
  let fetched = 0;
  let inserted = 0;
  try {
    const html = crawlByUrl.get(source.list_url) || crawlByUrl.get(absUrl(source.list_url, source.base_url)) || crawlByUrl.get('__fallback__') || '';
    if (!html) throw new Error('Crawl4AI did not return html/markdown for this source URL.');
    if (/Just a moment|cf-mitigated|challenges.cloudflare.com/i.test(html)) throw new Error('Blocked by anti-bot challenge. Use an allowed source, API, export, saved HTML, or screenshot/OCR for this source.');
    let scraped = extractListings(source, html);
    if ((source.extractor_config || {}).crawl_detail_pages && scraped.length) {
      const batchSize = Math.max(1, Number((source.extractor_config || {}).detail_batch_size || 10));
      const detailByUrl = new Map();
      for (let i = 0; i < scraped.length; i += batchSize) {
        const batchUrls = scraped.slice(i, i + batchSize).map((row) => row.source_url).filter(Boolean);
        const detailItems = await crawlDetailPages(batchUrls);
        for (const detail of detailItems) {
          const url = String(detail.url || detail.redirected_url || '').trim();
          const detailHtml = detail.html || detail.cleaned_html || detail.fit_html || detail.markdown?.raw_markdown || detail.markdown || '';
          if (url && detailHtml) detailByUrl.set(url, extractJacarsDetailFields(detailHtml));
        }
      }
      scraped = scraped.map((row) => {
        const detail = detailByUrl.get(row.source_url) || {};
        return {
          ...row,
          phone: detail.phone || row.phone || '',
          color: detail.color || row.color || '',
          transmission: detail.transmission || row.transmission || '',
          mileage_km: detail.mileage_km || row.mileage_km || '',
          description: detail.description || row.description || ''
        };
      });
    }
    fetched = scraped.length;
    for (const row of scraped) {
      const key = String(row.source_url || '').trim();
      if (!key) continue;
      rowsByUrl.set(key, { ...(rowsByUrl.get(key) || {}), ...row });
      inserted += 1;
    }
    summary.push({ source: source.name, status: 'success', fetched, inserted, mode: 'crawl4ai' });
  } catch (error) {
    summary.push({ source: source.name, status: 'failed', fetched, inserted, mode: 'crawl4ai', error: error.message });
  }
}
const nextRows = Array.from(rowsByUrl.values()).sort((a, b) => String(b.scraped_at || '').localeCompare(String(a.scraped_at || '')));
await putGithubCsv(toCsv(nextRows), existing.sha);
return summary.map((row) => ({ json: row }));
